import {groups,fields,parse,serialize,display,native,validate} from './model.mjs';
const $=s=>document.querySelector(s);let baseline='',changes={},sourceDirty=false;
const importControl=document.querySelector('label.button');importControl.tabIndex=0;importControl.setAttribute('role','button');importControl.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();$('#upload').click();}};
const current=()=>serialize(baseline,changes);
function notice(message){$('#notice').textContent=message;$('#notice').style.display='block';setTimeout(()=>$('#notice').style.display='none',3500);}
function review(){const text=current(),issues=validate(text,$('#solver').value),errors=issues.filter(i=>i.level==='error');$('#issues').replaceChildren(...issues.map(i=>{const el=document.createElement('div');el.className=`issue ${i.level}`;const title=document.createElement('strong');title.textContent=i.level==='info'?'Scope':i.level;el.append(title,document.createTextNode(i.message));return el;}));$('#status').textContent=sourceDirty?'Apply source edits to validate':errors.length?`${errors.length} issue${errors.length===1?'':'s'} to resolve`:'No blocking configuration errors';$('#export').disabled=errors.length>0||sourceDirty;$('#count').textContent=`${Object.keys(changes).length} parameter edits · ${issues.filter(i=>i.level==='warning').length} warnings`;}
function render(){const {values}=parse(current());$('#form').replaceChildren();groups.forEach(([name,list],index)=>{const section=document.createElement('section');section.className='group';const heading=document.createElement('h2');const n=document.createElement('span');n.className='index';n.textContent=`0${index+1}`;heading.append(n,name);section.append(heading);const grid=document.createElement('div');grid.className='fields';for(const f of list){const [key,label,unit]=f;const field=document.createElement('div');field.className='field';const lab=document.createElement('label');lab.htmlFor=key;lab.textContent=label;const wrap=document.createElement('div');wrap.className='input-wrap';const select=Array.isArray(unit);const input=document.createElement(select?'select':'input');input.id=key;if(select){if(!(key in values)){const opt=new Option('Default (not set)','');input.append(opt);}else if(!unit.includes(values[key]))input.append(new Option(values[key],values[key]));for(const value of unit)input.append(new Option(value==='0'?'Disabled':value==='1'?'Enabled':value,value));input.value=values[key]??'';}else{input.type='number';input.step='any';input.placeholder='Default (not set)';input.value=key in values?String(Number(display(values[key],f).toPrecision(12))):'';const suffix=document.createElement('span');suffix.className='unit';suffix.textContent=unit;wrap.append(suffix);}input.addEventListener('input',()=>{const value=input.value===''?'':select?input.value:native(input.value,f);changes[key]=value;if(value===parse(baseline).values[key])delete changes[key];review();});wrap.prepend(input);const hint=document.createElement('small');hint.textContent=`-${key}`;field.append(lab,wrap,hint);grid.append(field);}section.append(grid);$('#form').append(section);});review();}
function tab(source){$('#form').hidden=source;$('#sourcePanel').hidden=!source;$('#parameters').setAttribute('aria-selected',String(!source));$('#sourceTab').setAttribute('aria-selected',String(source));if(source&&!sourceDirty)$('#source').value=current();}
$('#sourceTab').onclick=()=>tab(true);$('#parameters').onclick=()=>{if(sourceDirty){notice('Apply your source changes before returning to parameters.');return;}tab(false);};
$('#source').oninput=()=>{sourceDirty=true;review();};
$('#apply').onclick=()=>{baseline=$('#source').value;changes={};sourceDirty=false;render();notice('Source applied. Review validation before exporting.');};
$('#reset').onclick=()=>{if((Object.keys(changes).length||sourceDirty)&&!confirm('Discard unapplied parameter and source edits?'))return;changes={};sourceDirty=false;render();$('#source').value=current();};
$('#solver').onchange=review;
$('#upload').onchange=async event=>{const file=event.target.files[0];if(!file)return;if(file.size>2000000){notice('Choose a configuration smaller than 2 MB.');return;}if((Object.keys(changes).length||sourceDirty)&&!confirm('Replace the current configuration and edits?'))return;baseline=await file.text();changes={};sourceDirty=false;$('#filename').textContent=file.name;render();tab(false);event.target.value='';};
$('#export').onclick=()=>{if(sourceDirty||validate(current(),$('#solver').value).some(i=>i.level==='error'))return;const url=URL.createObjectURL(new Blob([current()],{type:'text/plain'}));const a=document.createElement('a');a.href=url;a.download='tuned.config';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notice('Downloaded tuned.config');};
try{const response=await fetch('example.config');if(!response.ok)throw Error('Example not found');baseline=await response.text();render();}catch(error){$('#status').textContent='Could not load example';$('#export').disabled=true;$('#issues').textContent='Serve this directory over HTTP, or import your own configuration.';}
if(document.modelContext?.registerTool){try{await document.modelContext.registerTool({name:'inspect_hotspot_configuration',description:'Read the applied HotSpot configuration and its pre-run validation results. Does not run a simulation or include unapplied source edits.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute(input){if(input&&Object.keys(input).length)throw new Error('This tool takes no arguments.');return {parameters:parse(current()).values,issues:validate(current(),$('#solver').value),unappliedSourceEdits:sourceDirty};}});}catch(error){console.warn('Optional browser tool registration unavailable',error);}}
export function getRunConfiguration(){if(sourceDirty)throw Error('Apply source changes before running.');const errors=validate(current(),'off').filter(i=>i.level==='error');if(errors.length)throw Error(errors.map(i=>i.message).join('\n'));return current();}
